insert into public.places (id, name, area, lat, lng, tags, duration_min, cost_band, indoor, mrt, hours, closed_days, min_window_h, blurb, captions, safety_notes, image_url) values
  ('jewel-rain-vortex', 'Jewel Rain Vortex', 'Changi', 1.3602, 103.9894, array['photo', 'gardens', 'views', 'architecture']::text[], 40, 0, true, 'Changi Airport', '[["10:00","22:00"]]'::jsonb, '{}'::int[], null, 'The world''s tallest indoor waterfall pours 40 metres through a glass doughnut roof inside Jewel, a short walk from every terminal.', array['The waterfall is louder than you expect, stand at the B2 rail for the spray shot.', 'Evening light-and-sound show turns the vortex into a projection screen.', 'Walkable from T1 in 5 minutes, T2/T3 via linkbridge in 10.']::text[], 'Landside: you must clear immigration to reach it.', null),
  ('jewel-canopy-park', 'Canopy Park, Jewel', 'Changi', 1.3606, 103.9897, array['gardens', 'photo', 'nature']::text[], 60, 2, true, 'Changi Airport', '[["10:00","22:00"]]'::jsonb, '{}'::int[], null, 'Topiary walks, a hedge maze, mist bowls and a glass-floored bridge on Jewel''s top level, looking down on the Rain Vortex.', '{}'::text[], 'Ticketed; buy at the L5 counter or online.', null),
  ('jewel-forest-valley', 'Shiseido Forest Valley', 'Changi', 1.3598, 103.9898, array['gardens', 'nature', 'photo']::text[], 30, 0, true, 'Changi Airport', '"24h"'::jsonb, '{}'::int[], null, 'A terraced indoor forest of 2,000 trees and shrubs wrapping around the vortex, free, open all night, perfect for a jet-lag stroll.', '{}'::text[], null, null),
  ('changi-chapel-museum', 'Changi Chapel & Museum', 'Changi', 1.359, 103.9738, array['museum', 'heritage', 'culture']::text[], 60, 0, true, 'Changi Airport', '[["09:30","17:30"]]'::jsonb, array[1]::int[], null, 'Quiet, moving museum on the WWII prisoners of war held at Changi, with a replica of the chapel they built.', '{}'::text[], 'Closed Mondays. Taxi recommended from the airport.', null),
  ('changi-village-hawker', 'Changi Village Hawker Centre', 'Changi', 1.3893, 103.9876, array['hawker', 'food']::text[], 45, 1, true, 'Changi Airport', '[["07:00","23:00"]]'::jsonb, '{}'::int[], null, 'Seaside hawker centre famous for nasi lemak and satay bee hoon; planes glide overhead on approach to Changi.', '{}'::text[], 'No MRT nearby. Budget a taxi both ways.', null),
  ('changi-point-boardwalk', 'Changi Point Coastal Boardwalk', 'Changi', 1.3897, 103.9893, array['nature', 'views', 'photo', 'beach']::text[], 45, 0, false, 'Changi Airport', '"24h"'::jsonb, '{}'::int[], null, 'Timber boardwalk hugging the cliffs and mangroves of Changi Point, with views across to Pulau Ubin and Malaysia.', '{}'::text[], null, null),
  ('changi-beach-park', 'Changi Beach Park', 'Changi', 1.3913, 103.9918, array['beach', 'nature', 'photo']::text[], 40, 0, false, 'Changi Airport', '"24h"'::jsonb, '{}'::int[], null, 'Long, quiet beach at the island''s eastern tip. Best at sunset when the jets line up overhead.', '{}'::text[], null, null),
