  ('east-coast-park', 'East Coast Park (Marine Cove)', 'East Coast', 1.3002, 103.913, array['beach', 'nature', 'photo']::text[], 45, 0, false, 'Marine Parade', '"24h"'::jsonb, '{}'::int[], null, '15 km of coastal park; rent a bike or just walk the promenade and watch container ships queue offshore.', '{}'::text[], null, null),
  ('koon-seng-shophouses', 'Koon Seng Road Peranakan Houses', 'East Coast', 1.3143, 103.9021, array['photo', 'heritage', 'architecture']::text[], 20, 0, false, 'Eunos', '"24h"'::jsonb, '{}'::int[], null, 'Row of candy-coloured Peranakan terrace houses with ornate tiles, Singapore''s most photographed doorways.', '{}'::text[], 'Residents live here. Keep voices down and stay off the five-foot ways.', null),
