  ('old-airport-road', 'Old Airport Road Food Centre', 'East Coast', 1.3081, 103.8858, array['hawker', 'food']::text[], 45, 1, true, 'Dakota', '[["07:00","22:00"]]'::jsonb, '{}'::int[], null, 'Built on Singapore''s first airport runway; 150 stalls, many of them local legends for char kway teow and lor mee.', '{}'::text[], null, null),
  ('supertree-grove', 'Supertree Grove', 'Marina Bay', 1.2816, 103.8636, array['gardens', 'photo', 'views', 'nature']::text[], 45, 0, false, 'Bayfront', '[["05:00","23:59"]]'::jsonb, '{}'::int[], null, 'Eighteen vertical gardens up to 50 m tall, the postcard of modern Singapore. Free to walk beneath.', array['Lie on the ground at 7:45 pm for Garden Rhapsody, the trees sing.', 'OCBC Skyway is a narrow 22 m-high walkway; closes in lightning.', 'Best photo: from the Dragonfly Bridge looking back at MBS.']::text[], 'Fully exposed: skip in thunderstorms, bring water at midday.', null),
  ('cloud-forest', 'Cloud Forest', 'Marina Bay', 1.284, 103.8659, array['gardens', 'nature', 'photo']::text[], 60, 3, true, 'Gardens by the Bay', '[["09:00","21:00"]]'::jsonb, '{}'::int[], null, 'A cool, misty dome with a 35 m indoor mountain and a waterfall; walk the aerial path through the cloud.', array['Instant relief from the humidity, it''s 23°C inside.', 'Take the lift to the top and walk down the Cloud Walk.', 'Waterfall mist is strongest right when you walk in.']::text[], null, null),
  ('flower-dome', 'Flower Dome', 'Marina Bay', 1.2842, 103.8642, array['gardens', 'photo']::text[], 45, 3, true, 'Bayfront', '[["09:00","21:00"]]'::jsonb, '{}'::int[], null, 'The world''s largest glass greenhouse, with Mediterranean gardens and a rotating seasonal flower show.', '{}'::text[], null, null),
