  ('mbs-skypark', 'Marina Bay Sands SkyPark', 'Marina Bay', 1.283, 103.8607, array['views', 'photo']::text[], 45, 3, false, 'Bayfront', '[["10:00","22:00"]]'::jsonb, '{}'::int[], null, 'Observation deck 57 floors up on the ship-shaped roof; 360° views of the bay, the Gardens and the straits.', '{}'::text[], 'Outdoor deck. Closes in lightning.', null),
  ('spectra-show', 'Spectra light & water show', 'Marina Bay', 1.2837, 103.8594, array['photo', 'nightlife', 'views']::text[], 20, 0, false, 'Bayfront', '[["19:50","21:15"]]'::jsonb, '{}'::int[], null, 'Free fountain, laser and projection show on the MBS Event Plaza at 8 and 9 pm.', '{}'::text[], null, null),
