  ('artscience-museum', 'ArtScience Museum', 'Marina Bay', 1.2863, 103.8593, array['museum', 'art']::text[], 75, 2, true, 'Bayfront', '[["10:00","19:00"]]'::jsonb, '{}'::int[], null, 'Lotus-shaped museum with immersive digital art (Future World) and big touring exhibitions.', array['Future World is a hit with anyone who likes glowing rooms.', 'The lotus roof collects rainwater into a centre waterfall.', 'Book a timed slot on weekends.']::text[], null, null),
  ('helix-bridge', 'Helix Bridge', 'Marina Bay', 1.2876, 103.8604, array['photo', 'architecture', 'views']::text[], 15, 0, false, 'Promenade', '"24h"'::jsonb, '{}'::int[], null, 'DNA-inspired steel footbridge that frames the MBS towers; lit up after dark.', '{}'::text[], null, null),
  ('merlion-park', 'Merlion Park', 'Marina Bay', 1.2868, 103.8545, array['photo', 'views']::text[], 25, 0, false, 'Raffles Place', '"24h"'::jsonb, '{}'::int[], null, 'The half-lion, half-fish mascot spouting into the bay, with MBS as the backdrop. Required selfie.', array['Everyone does the ''drinking the fountain'' photo. Everyone.', 'Come before 9 am to beat the tour buses.', 'The mini Merlion cub is behind the big one.']::text[], null, null),
